  for (let i = 0; i <= samples; i++) {
    const dt = (i / samples) * horizon;
    const weight = 1.0;
    const w = windAt(params, t + dt);
    wx += weight * w.x; wy += weight * w.y; wz += weight * w.z;
    wsum += weight;
  }
  return { x: wx / wsum, y: wy / wsum, z: wz / wsum };
