    const rollNom = clamp(-Math.asin(clamp(Fbz / Fnorm, -1, 1)), -0.55, 0.55);
    const pitchNom = clamp(Math.atan2(Fbx, Fy), -0.55, 0.55);
    const yawRateNom = clamp(-2.0 * att.yaw, -2, 2);

    // Total thrust so vertical force matches Fy at current or desired attitude
    const cosTilt = Math.max(0.5, Math.cos(att.roll) * Math.cos(att.pitch));
    const Ftotal = clamp(Fy / cosTilt, 0, 16);

